library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
library UNISIM;
use UNISIM.VCOMPONENTS.ALL;
entity CARRY_SAVE is
  port (
    clk : in STD_LOGIC;
    rst : in STD_LOGIC;
    OP1 : in STD_LOGIC_VECTOR ( 11 downto 0 );
    OP2 : in STD_LOGIC_VECTOR ( 11 downto 0 );
    OP3 : in STD_LOGIC_VECTOR ( 11 downto 0 );
    OP4 : in STD_LOGIC_VECTOR ( 11 downto 0 );
    FINAL_RIS : out STD_LOGIC_VECTOR ( 20 downto 0 )
  );
end CARRY_SAVE;

architecture STRUCTURE of CARRY_SAVE is
  signal SP1 : STD_LOGIC_VECTOR ( 18 downto 2 );
  signal SP2 : STD_LOGIC_VECTOR ( 19 downto 0 );
  signal VR1 : STD_LOGIC_VECTOR ( 18 downto 5 );
  signal VR2 : STD_LOGIC_VECTOR ( 19 downto 3 );
  signal op4_out : STD_LOGIC_VECTOR ( 18 downto 0 );
  signal NLW_BLOCCO1_SP_UNCONNECTED : STD_LOGIC_VECTOR ( 1 downto 0 );
  signal NLW_BLOCCO1_VR_UNCONNECTED : STD_LOGIC_VECTOR ( 4 downto 0 );
  signal NLW_BLOCCO2_VR_UNCONNECTED : STD_LOGIC_VECTOR ( 2 downto 0 );
  signal NLW_BLOCCO2_op1_UNCONNECTED : STD_LOGIC_VECTOR ( 1 downto 0 );
  signal NLW_BLOCCO2_op2_UNCONNECTED : STD_LOGIC_VECTOR ( 4 downto 0 );
  signal NLW_FINAL_Cin_UNCONNECTED : STD_LOGIC;
  signal NLW_FINAL_B_UNCONNECTED : STD_LOGIC_VECTOR ( 2 downto 0 );
  signal NLW_FINAL_Sum_UNCONNECTED : STD_LOGIC_VECTOR ( 20 downto 18 );
begin
  FINAL_RIS(18) <= 'Z';
  FINAL_RIS(19) <= 'Z';
  FINAL_RIS(20) <= 'Z';
BLOCCO1: entity work.STEP1
     port map (
      SP(18 downto 2) => SP1(18 downto 2),
      SP(1 downto 0) => NLW_BLOCCO1_SP_UNCONNECTED(1 downto 0),
      VR(18 downto 5) => VR1(18 downto 5),
      VR(4 downto 0) => NLW_BLOCCO1_VR_UNCONNECTED(4 downto 0),
      clk => clk,
      op1(11 downto 0) => OP1(11 downto 0),
      op2(11 downto 0) => OP2(11 downto 0),
      op3(11 downto 0) => OP3(11 downto 0),
      op4(11 downto 0) => OP4(11 downto 0),
      op4_out(18 downto 0) => op4_out(18 downto 0),
      rst => rst
    );
BLOCCO2: entity work.STEP2
     port map (
      SP(19 downto 0) => SP2(19 downto 0),
      VR(19 downto 3) => VR2(19 downto 3),
      VR(2 downto 0) => NLW_BLOCCO2_VR_UNCONNECTED(2 downto 0),
      clk => clk,
      op1(18 downto 2) => SP1(18 downto 2),
      op1(1 downto 0) => NLW_BLOCCO2_op1_UNCONNECTED(1 downto 0),
      op2(18 downto 5) => VR1(18 downto 5),
      op2(4 downto 0) => NLW_BLOCCO2_op2_UNCONNECTED(4 downto 0),
      op3(18 downto 0) => op4_out(18 downto 0),
      rst => rst
    );
FINAL: entity work.Pipeline
     port map (
      A(19 downto 0) => SP2(19 downto 0),
      B(19 downto 3) => VR2(19 downto 3),
      B(2 downto 0) => NLW_FINAL_B_UNCONNECTED(2 downto 0),
      Cin => NLW_FINAL_Cin_UNCONNECTED,
      Sum(20 downto 18) => NLW_FINAL_Sum_UNCONNECTED(20 downto 18),
      Sum(17 downto 0) => FINAL_RIS(17 downto 0),
      clock => clk,
      reset => rst
    );
end STRUCTURE;
